(function(){
'use strict';
const pages=['Suppliers & upgrades','Freight hub','Supply chain','Freight incidents'];
const regions=['Northland','Auckland','Waikato','Bay of Plenty','Gisborne','Hawke’s Bay','Taranaki','Manawatū-Whanganui','Wellington','Tasman','Nelson','Marlborough','West Coast','Canterbury','Otago','Southland','Chatham Islands'];
const priorities=['Preferred','Approved alternative','Backup','Under review'];
const categories=['Structural steel','Cladding & roofing','Windows & doors','Insulation','Fixings & hardware','Rainwater','Interior package','Freight','Other'];
const stages=['Planning','Supplier ready','SH dispatch','Carrier collection','In transit','Customer receipt','On hold'];
const incidentStages=['Reported','Assessing','Awaiting evidence','Replacement arranged','Resolved'];
const id=()=>globalThis.crypto?.randomUUID?.()||`logistics-${Date.now()}-${Math.random()}`;
const now=()=>new Date().toISOString();
function init(c){for(const k of ['suppliers','upgrades','shipments','freightIncidents','deliveryReceipts','inventory'])c.store[k] ||= []}
function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
const card=(title,body)=>`<section class="card sl-card"><h2>${title}</h2>${body}</section>`;
function frame(title,desc,body){return `<div class="sl-module"><div class="heading"><div><div class="eyebrow">SHED HOUSE / LOGISTICS</div><h1>${title}</h1><p>${desc}</p></div><span class="tag amber">Local demo · manual records</span></div>${body}</div>`}
function opts(items,selected,e){return items.map(x=>`<option value="${e(x)}" ${x===selected?'selected':''}>${e(x)}</option>`).join('')}
function field(label,name,value='',extra=''){return `<label>${label}<input name="${name}" value="${String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}" ${extra}></label>`}
function select(label,name,items,value,e){return `<label>${label}<select name="${name}">${opts(items,value,e)}</select></label>`}
function supplierOptions(c,value){return `<option value="">Select supplier</option>${c.store.suppliers.map(s=>`<option value="${c.escape(s.id)}" ${s.id===value?'selected':''}>${c.escape(s.name)} · ${c.escape(s.priority)}</option>`).join('')}`}
function projectSelector(c){return `<label class="sl-project">Project<select id="sl-project">${c.projects.map(p=>`<option value="${c.escape(p.id)}" ${p.id===c.projectId?'selected':''}>${c.escape(p.name)} · ${c.escape(p.id)}</option>`).join('')}</select></label>`}
function supplierName(c,idValue){return c.store.suppliers.find(x=>x.id===idValue)?.name||'Supplier unassigned'}
function shipmentOptions(c){return `<option value="">Select shipment</option>${c.store.shipments.filter(s=>s.projectId===c.projectId).map(s=>`<option value="${c.escape(s.id)}">${c.escape(s.trackingNumber||s.id)} · ${c.escape(s.carrier)}</option>`).join('')}`}
function render(page,c){init(c);const e=c.escape,s=c.store,pr=c.projectId;
if(page==='Suppliers & upgrades')return frame('The right supply. A considered upgrade.','Maintain SH’s supplier priorities and customer upgrade packages with a clear price basis.',`<div class="sl-grid">${card('Supplier register',`<p class="small">No preferred partners are preselected. Record verified availability evidence and SH approval before setting a priority.</p><div class="table-wrap"><table><thead><tr><th>Supplier / material</th><th>Priority / rank</th><th>Region & availability evidence</th><th></th></tr></thead><tbody>${s.suppliers.slice().sort((a,b)=>(a.rank||999)-(b.rank||999)).map(x=>`<tr><td><strong>${e(x.name)}</strong>${e(x.category)}</td><td><span class="tag ${x.priority==='Preferred'?'':'grey'}">${e(x.priority)}</span><p>Rank ${e(x.rank||'Unset')}</p></td><td>${e(x.region)}<p>${e(x.notes||'Evidence not recorded')}</p><span class="small">Checked: ${e(x.checkedAt||'Not recorded')}</span></td><td><button class="link" data-sl-supplier="${e(x.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="4">Add your supplier network below.</td></tr>'}</tbody></table></div><form id="sl-supplier" class="sl-form"><input type="hidden" name="id">${field('Supplier name','name','','required')}${select('Material category','category',categories,'',e)}${select('SH priority','priority',priorities,'Under review',e)}${field('Priority rank within category','rank','','type="number" min="1" step="1"')}${select('Primary NZ region','region',regions,'',e)}${field('Availability checked on','checkedAt','','type="date"')}<label class="sl-wide">Availability evidence / lead time / contact / approval notes<textarea name="notes" required placeholder="Supplier quote reference, material availability, checked date and SH approval…"></textarea></label><button class="primary">Save supplier</button><button type="reset" class="secondary">Clear form</button></form>`)}${card('Upgrade packages',`<p>Customer price is a <strong>delta above the contracted baseline kitset</strong>, excluding GST. State exactly what is replaced, included and excluded.</p>${s.upgrades.map(u=>`<article class="sl-record"><span class="tag">${e(u.status)}</span><h3>${e(u.name)}</h3><p>${e(u.description)}</p><p>${e(u.category)} · ${e(supplierName(c,u.supplierId))}</p><strong>+ ${c.money(u.priceExGst)} excl. GST</strong><p class="small">+ ${c.money(u.priceExGst*1.15)} incl. 15% GST · ${e(u.basis||'Delta above contracted baseline')}</p><button class="link" data-sl-upgrade="${e(u.id)}">Edit package</button></article>`).join('')||'<p class="small">No packages yet. Confirm a supplier and baseline before offering an upgrade.</p>'}<form id="sl-upgrade" class="sl-form"><input type="hidden" name="id">${field('Package name','name','','required')}${select('Category','category',categories,'',e)}<label>Supplier<select name="supplierId" required>${supplierOptions(c)}</select></label>${field('Customer delta NZD excl. GST','priceExGst','','type="number" min="0" step="0.01" required')}${select('Catalogue status','status',['Draft','Available','Unavailable'],'Draft',e)}${field('Price basis / baseline reference','basis','','required')}<label class="sl-wide">Package specification, inclusions & exclusions<textarea name="description" required></textarea></label><button class="primary">Save upgrade package</button><button type="reset" class="secondary">Clear form</button></form>`)}</div>`);
if(page==='Freight hub'){const shipments=s.shipments.filter(x=>x.projectId===pr);return frame('Across New Zealand. In one view.','Coordinate kitset movements with supplier, project and inventory references.',projectSelector(c)+`<div class="banner"><div><h2>Manual tracking register</h2><p>Dates and statuses are entered by SH. Carrier links open the carrier’s service; this portal has no live tracking connection.</p></div></div><div class="sl-grid">${card('Project freight register',shipments.map(x=>`<article class="sl-record"><span class="tag ${x.status==='On hold'?'amber':'grey'}">${e(x.status)}</span><h3>${e(x.carrier)} · ${e(x.trackingNumber||'Reference pending')}</h3><p>${e(x.origin)} → ${e(x.destination)}</p><p>${e(x.region)} · Expected ${e(x.expectedDate||'Not scheduled')} · ${e(supplierName(c,x.supplierId))}</p><span class="small">Shipment ${e(x.id)}</span><p>${safeURL(x.trackingUrl)?`<a href="${e(safeURL(x.trackingUrl))}" rel="noopener noreferrer" target="_blank">Open carrier tracking ↗</a>`:'Tracking link not recorded'}</p><button class="link" data-sl-shipment="${e(x.id)}">Edit shipment</button><details><summary>Manifest · ${(x.manifest||[]).length} lines</summary>${manifestTable(x,c)}</details></article>`).join('')||'<p>No shipments scheduled for this project.</p>')}${card('Create or edit shipment',`<form id="sl-shipment" class="sl-form"><input type="hidden" name="id"><label>Supplier<select name="supplierId" required>${supplierOptions(c)}</select></label>${field('Carrier','carrier','','required')}${field('Consignment / tracking reference','trackingNumber')}${field('Carrier tracking HTTPS URL','trackingUrl','','type="url" placeholder="https://…"')}${field('Origin / pickup address','origin','','required')}${field('Destination / delivery address','destination','','required')}${select('Destination NZ region','region',regions,'',e)}${field('Expected delivery date','expectedDate','','type="date"')}${select('Status','status',stages,'Planning',e)}<p class="small sl-wide">Shipment status edits are retained as manual events. Expected dates are estimates.</p><button class="primary">Save shipment</button><button type="reset" class="secondary">Clear form</button></form><hr><h3>Add manifest line</h3><form id="sl-manifest" class="sl-form"><label>Shipment<select name="shipmentId" required>${shipmentOptions(c)}</select></label><label>Kitset inventory item<select name="inventoryId"><option value="">Custom freight item</option>${s.inventory.filter(x=>x.projectId===pr).map(x=>`<option value="${e(x.id)}">${e(x.category)} / ${e(x.name)}</option>`).join('')}</select></label>${field('Item name (if custom)','item')}${field('Quantity in this shipment','qty','','type="number" min="0.01" step="0.01" required')}${field('Unit','unit','ea','required')}<button class="primary">Add to manifest</button></form>`)}</div>`)}
if(page==='Supply chain')return frame('Supplier ready. Customer received.','Track handover responsibilities and supporting records across the supply chain.',projectSelector(c)+s.shipments.filter(x=>x.projectId===pr).map(x=>card(`${e(x.carrier)} · ${e(x.trackingNumber||x.id)}`,`<p>${e(supplierName(c,x.supplierId))} · ${e(x.origin)} → ${e(x.destination)}</p><div class="sl-chain">${['Supplier ready','SH dispatch','Carrier collection','Customer receipt'].map(stage=>{const event=(x.events||[]).findLast(y=>y.status===stage);const receipt=stage==='Customer receipt'&&s.deliveryReceipts.find(r=>r.shipmentId===x.id&&r.projectId===pr);return `<div class="${event||receipt?'sl-complete':''}"><span>${event||receipt?'✓':'○'}</span><h3>${stage}</h3><p class="small">${event?`${e(event.at)} · ${e(event.location||'')} · Manual`:receipt?`${e(receipt.receivedAt)} · ${e(receipt.receivedBy)} · Customer record`:'Awaiting recorded handover'}</p></div>`}).join('')}</div>${x.status==='On hold'?'<p class="sl-alert">Shipment is on hold. Resolve the incident assessment before releasing affected materials.</p>':''}<div class="sl-grid"><section><h3>Manual handover update</h3><form data-sl-event="${e(x.id)}" class="sl-form">${select('Milestone / status','status',stages,x.status,e)}${field('Location','location','','required')}${field('Event date & time','at','','type="datetime-local" required')}<label class="sl-wide">Evidence / chain reference / handover notes<textarea name="note" required></textarea></label><button class="primary">Record manual event</button></form></section><section><h3>Traceable activity</h3>${(x.events||[]).slice().reverse().map(ev=>`<article class="sl-record"><strong>${e(ev.status)}</strong><p>${e(ev.note)}</p><span class="small">${e(ev.at)} · ${e(ev.location)} · ${e(ev.source||'Manual')}</span></article>`).join('')||'<p>No recorded events.</p>'}${s.deliveryReceipts.filter(r=>r.shipmentId===x.id&&r.projectId===pr).map(r=>`<article class="sl-record"><strong>Customer delivery receipt</strong><p>${e(r.condition)} · ${e(r.notes||'')}</p><span class="small">${e(r.receivedBy)} · ${e(r.receivedAt)}</span></article>`).join('')}</section></div>`)).join('')+(!s.shipments.some(x=>x.projectId===pr)?card('Ready to coordinate','<p>Create a shipment in Freight hub, then record supplier, SH, carrier and customer handovers here.</p>'):'')+card('Mainfreight integration roadmap',`<p>Official Mainfreight tracking and webhook APIs support status updates and freight references. A future server integration requires registration, credentials, secured webhook handling and a verified shipment mapping.</p><p class="small">No carrier API connection is active in this demo.</p><p><a href="https://developer.mainfreight.com/global/en/global-home/getting-started.aspx" target="_blank" rel="noopener noreferrer">Official API registration & tracking documentation ↗</a></p><p><a href="https://developer.mainfreight.com/global/en/global-home/subscription-api/tracking-update-webhook.aspx" target="_blank" rel="noopener noreferrer">Official tracking webhook documentation ↗</a></p>`));
if(page==='Freight incidents')return frame('Report. Assess. Resolve.','Manage customer freight issues with clear ownership and an evidence trail.',projectSelector(c)+`<div class="banner"><div><h2>Keep affected material separate</h2><p>Damaged, missing or unsafe material needs assessment. Do not install affected components until an authorised assessment confirms the appropriate action. Record the delivery condition and request evidence.</p></div></div>`+s.freightIncidents.filter(x=>x.projectId===pr).map(x=>card(`${e(x.type)} · ${e(x.item||'Freight issue')}`,`<span class="tag ${x.status==='Resolved'?'':'amber'}">${e(x.status)}</span><p>${e(x.description)}</p><p>Shipment ${e(x.shipmentId||'Unassigned')} · Quantity ${e(x.qty??'Not recorded')} · Reported ${e(x.createdAt)}</p><div class="sl-grid"><section><form data-sl-incident="${e(x.id)}" class="sl-form">${field('Assigned SH owner','owner',x.owner||'','required')}${select('Assessment status','status',incidentStages,x.status,e)}${field('Carrier / supplier case reference','caseReference',x.caseReference||'')}<label class="sl-wide">Assessment, requested evidence & next action<textarea name="decision" required>${e(x.decision||'')}</textarea></label><label class="sl-wide">Resolution confirmation / customer acknowledgement<textarea name="resolution">${e(x.resolution||'')}</textarea></label><label class="sl-wide sl-check"><input name="hold" type="checkbox" ${x.hold!==false&&x.status!=='Resolved'?'checked':''}> Hold affected material pending assessment</label><p class="small sl-wide">Resolve only after recording the remedy and confirmation. Payment, carrier claims and statutory rights require separate review.</p><button class="primary">Save protocol update</button></form></section><section><h3>Evidence</h3>${(x.attachments||[]).map(a=>{const aid=typeof a==='string'?a:a.id;return `<p><button class="link" data-sl-evidence="${e(aid)}" data-owner="${e(x.id)}">Download ${e(typeof a==='string'?'attachment':a.name||'attachment')}</button></p>`}).join('')||'<p>No evidence attached. Request delivery photos, manifest discrepancies and supplier references.</p>'}<h3>Assessment history</h3>${(x.history||[]).slice().reverse().map(h=>`<article class="sl-record"><strong>${e(h.status||'Update')}</strong><p>${e(h.note||h.decision||'')}</p><span class="small">${e(h.at||h.createdAt||'')} · ${e(h.owner||'')}</span></article>`).join('')||'<p>No SH assessment yet.</p>'}</section></div>`)).join('')+(!s.freightIncidents.some(x=>x.projectId===pr)?card('No reported incidents','<p>Customer freight reports appear here for SH assessment. Customer-reported delivery problems remain scoped to their project.</p>'):'')+card('Report on behalf of customer',`<form id="sl-report" class="sl-form"><label>Shipment<select name="shipmentId" required>${shipmentOptions(c)}</select></label>${select('Issue type','type',['Damaged','Missing','Unsafe','Other'],'',e)}${field('Affected item','item','','required')}${field('Quantity affected','qty','1','type="number" min="0.01" step="0.01" required')}<label class="sl-wide">Customer report / delivery condition<textarea name="description" required></textarea></label><button class="primary">Create incident & hold shipment</button></form>`));
return '';
}
function manifestTable(x,c){return `<div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantity</th><th>Inventory reference</th></tr></thead><tbody>${(x.manifest||[]).map(m=>`<tr><td>${c.escape(m.item)}</td><td>${c.escape(m.qty)} ${c.escape(m.unit)}</td><td>${c.escape(m.inventoryId||'Custom')}</td></tr>`).join('')||'<tr><td colspan="3">Manifest not populated.</td></tr>'}</tbody></table></div>`}
function bind(page,c){init(c);const s=c.store,$=q=>document.querySelector(q),refresh=()=>{c.save();c.navigate(page)},notice=(title,message,kind='freight')=>c.notify({title,message,kind,projectId:c.projectId,roles:['staff','customer','contractor']});
const on=(q,event,fn)=>{const el=$(q);if(el)el.addEventListener(event,fn)};
const form=(q,fn)=>on(q,'submit',async ev=>{ev.preventDefault();try{const ok=await fn(Object.fromEntries(new FormData(ev.target)),ev.target);if(ok!==false)refresh()}catch(err){c.toast('Unable to save this local record. Please retry.')}});
const projectShipment=key=>s.shipments.find(x=>x.id===key&&x.projectId===c.projectId);
const edit=(attr,records,formId,scope=false)=>document.querySelectorAll(`[${attr}]`).forEach(el=>el.onclick=()=>{const record=records.find(x=>x.id===el.getAttribute(attr)&&(!scope||x.projectId===c.projectId));if(!record)return;const f=$(formId);for(const [k,v]of Object.entries(record))if(f.elements[k])f.elements[k].value=v;f.scrollIntoView({behavior:'smooth',block:'center'})});
on('#sl-project','change',ev=>{s.staffProjectId=ev.target.value;refresh()});
form('#sl-supplier',d=>{const rank=d.rank?Number(d.rank):null;const x={...d,id:d.id||id(),rank,updatedAt:now()};const i=s.suppliers.findIndex(y=>y.id===x.id);if(i<0)s.suppliers.push(x);else s.suppliers[i]=x;c.toast('Supplier priorities saved')});edit('data-sl-supplier',s.suppliers,'#sl-supplier');
form('#sl-upgrade',d=>{if(!s.suppliers.some(x=>x.id===d.supplierId)){c.toast('Select a registered supplier');return false}const x={...d,id:d.id||id(),priceExGst:Number(d.priceExGst),updatedAt:now()};const i=s.upgrades.findIndex(y=>y.id===x.id);if(i<0)s.upgrades.push(x);else s.upgrades[i]=x;c.toast('Customer upgrade catalogue saved')});edit('data-sl-upgrade',s.upgrades,'#sl-upgrade');
form('#sl-shipment',d=>{if(d.trackingUrl&&!safeURL(d.trackingUrl)){c.toast('Carrier tracking must use a valid HTTPS URL');return false}if(!s.suppliers.some(x=>x.id===d.supplierId)){c.toast('Select a registered supplier');return false}const old=d.id?projectShipment(d.id):null;if(d.id&&!old)return false;const unresolved=s.freightIncidents.some(i=>i.shipmentId===d.id&&i.projectId===c.projectId&&i.status!=='Resolved'&&i.hold!==false);if(unresolved&&d.status!=='On hold'){c.toast('Assess the active freight hold before releasing this shipment');return false}const x={...d,id:old?.id||id(),projectId:c.projectId,manifest:old?.manifest||[],events:old?.events||[]};if(!old||old.status!==d.status)x.events.push({id:id(),status:d.status,location:d.origin,note:'Shipment register update',at:now(),source:'Manual'});if(old)s.shipments[s.shipments.indexOf(old)]=x;else s.shipments.push(x);notice('Freight schedule updated',`${d.carrier} · ${d.trackingNumber||'Tracking reference pending'} · ${d.status}`);c.toast('Manual freight record saved')});edit('data-sl-shipment',s.shipments,'#sl-shipment',true);
form('#sl-manifest',d=>{const sh=projectShipment(d.shipmentId);if(!sh)return false;const inv=d.inventoryId?s.inventory.find(x=>x.id===d.inventoryId&&x.projectId===c.projectId):null;if(d.inventoryId&&!inv)return false;const item=inv?.name||d.item.trim();if(!item){c.toast('Select an inventory item or name the custom freight item');return false}sh.manifest||=[];sh.manifest.push({inventoryId:inv?.id||'',item,qty:Number(d.qty),unit:d.unit});c.toast('Manifest item added')});
document.querySelectorAll('[data-sl-event]').forEach(f=>f.addEventListener('submit',ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(f)),sh=projectShipment(f.dataset.slEvent);if(!sh)return;if(s.freightIncidents.some(i=>i.shipmentId===sh.id&&i.projectId===c.projectId&&i.status!=='Resolved'&&i.hold!==false)&&d.status!=='On hold'){c.toast('Active incident hold must be assessed before progressing freight');return}const at=new Date(d.at);if(!Number.isFinite(at.getTime())){c.toast('Enter a valid event date');return}sh.events||=[];sh.events.push({id:id(),status:d.status,location:d.location,note:d.note,at:at.toISOString(),source:'Manual'});sh.status=d.status;notice('Supply chain milestone recorded',`${sh.trackingNumber||sh.id}: ${d.status}`);refresh()}));
form('#sl-report',d=>{const sh=projectShipment(d.shipmentId);if(!sh)return false;const x={...d,id:id(),projectId:c.projectId,qty:Number(d.qty),status:'Reported',createdAt:now(),attachments:[],owner:'',decision:'',caseReference:'',hold:true,history:[{status:'Reported',note:d.description,at:now(),owner:'SH report'}]};s.freightIncidents.push(x);sh.status='On hold';sh.events||=[];sh.events.push({id:id(),status:'On hold',location:sh.destination,note:`Incident ${x.id}: ${d.type}`,at:now(),source:'Manual'});notice('Freight issue reported',`${d.type}: ${d.item}. Affected materials are on hold.`,'freight-incident');c.toast('Incident recorded for assessment')});
document.querySelectorAll('[data-sl-incident]').forEach(f=>f.addEventListener('submit',ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(f)),x=s.freightIncidents.find(i=>i.id===f.dataset.slIncident&&i.projectId===c.projectId);if(!x)return;if(d.status==='Resolved'&&!d.resolution.trim()){c.toast('Record the remedy and resolution confirmation before resolving');return}if(d.status==='Resolved'&&d.hold==='on'){c.toast('Clear the affected material hold after authorised assessment before resolving');return}Object.assign(x,{owner:d.owner,status:d.status,decision:d.decision,caseReference:d.caseReference,resolution:d.resolution,hold:d.hold==='on'});x.history||=[];x.history.push({status:d.status,note:d.decision,owner:d.owner,at:now(),resolution:d.resolution,hold:x.hold});const sh=projectShipment(x.shipmentId);if(sh&&x.hold){sh.status='On hold';sh.events||=[];sh.events.push({id:id(),status:'On hold',location:sh.destination,note:`Incident assessment: ${d.decision}`,at:now(),source:'Manual'})}notice('Freight assessment updated',`${x.item}: ${d.status} · Owner ${d.owner}`,'freight-incident');c.toast(d.status==='Resolved'?'Resolution recorded; review shipment status separately':'Assessment recorded');refresh()}));
document.querySelectorAll('[data-sl-evidence]').forEach(button=>button.onclick=async()=>{try{const incident=s.freightIncidents.find(x=>x.id===button.dataset.owner&&x.projectId===c.projectId);if(!incident||!c.files){c.toast('Local evidence storage is unavailable');return}const record=await c.files.get(button.dataset.slEvidence);if(!record||record.projectId!==c.projectId||record.ownerId!==incident.id||!record.blob){c.toast('Evidence unavailable on this device');return}const url=URL.createObjectURL(record.blob),a=document.createElement('a');a.href=url;a.download=record.name||'freight-evidence';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{c.toast('Unable to retrieve local evidence')}});
}
window.SHLogistics={pages,render,bind};
})();
